"use client"

import { useCallback, useMemo, useState, type ReactNode } from "react"

import {
  FILTER_CONTROLS,
  NO_STAGE,
  activeFilters,
  countByStage,
  filterOptions,
  filterTasks,
  groupByStatus,
  summarize,
  type ColumnConfig,
  type TaskFilters,
} from "@/lib/agent-task-board-model"
import type { AgentTaskBoardProps, ColumnAccent } from "@/components/ui/agent-task-board-props"
import { cn } from "@/lib/utils"
import {
  AgentTaskBoardRoot,
  AgentTaskProposalsRoot,
  createAgentTaskBoardController,
} from "@/components/ui/agent-task-board-root"
import { AgentTaskBoardBacklog } from "@/components/ui/agent-task-board-backlog"
import { AgentTaskBoardColumns, withColumn } from "@/components/ui/agent-task-board-columns"
import { AgentTaskBoardDetail } from "@/components/ui/agent-task-board-detail"
import { AgentTaskBoardEmpty } from "@/components/ui/agent-task-board-empty"
import { AgentTaskBoardSummary } from "@/components/ui/agent-task-board-summary"
import { AgentTaskBoardTable } from "@/components/ui/agent-task-board-table"
import { AgentTaskBoardToolbar, clearedFilters } from "@/components/ui/agent-task-board-toolbar"
import { agentTaskBoardLabels, agentTaskBoardLabelsEs, resolveLabels } from "@/components/ui/agent-task-labels"
import { useNow } from "@/components/ui/relative-time"
import type { TaskDisplayOptions } from "@/components/ui/task-card"
import { taskStatusAccentTones } from "@/components/ui/task-status"
import { useBoardFocus } from "@/components/ui/use-board-focus"

const NO_FILTERS: TaskFilters = {}
const NO_COLUMNS: ColumnConfig[] = []

function useControllable<T>(value: T | undefined, initial: T) {
  const [own, setOwn] = useState(initial)
  return [value === undefined ? own : value, setOwn] as const
}

function pageLocale() {
  return typeof document === "undefined" ? undefined : document.documentElement.lang || undefined
}

function AgentTaskBoard(props: AgentTaskBoardProps) {
  const { tasks, mode, generatedAt, formatCurrency, timeZone, agentApproval = "confirm" } = props
  const { onApproveProposal, onRejectProposal, renderThreadLink, onOpenThread } = props
  const { detailPresentation = "dialog", density = "auto", agentAvatars, columnAccent = "tint" } = props
  const { renderLink, onOpenLink, renderAttachments, renderLocation, stages } = props
  const { renderBacklogActions, renderCardActions, filterControls = FILTER_CONTROLS } = props
  const tones = useMemo(() => ({ ...taskStatusAccentTones, ...props.columnTones }), [props.columnTones])
  const labels = useMemo(() => resolveLabels(props.labels), [props.labels])
  const now = useNow({ now: mode === "snapshot" ? generatedAt : props.now })
  const locale = props.locale ?? pageLocale()
  const [controller] = useState(createAgentTaskBoardController)
  const [view, setView] = useControllable(props.view, props.defaultView ?? "board")
  const [filters, setFilters] = useControllable(props.filters, props.defaultFilters ?? NO_FILTERS)
  const [columns, setColumns] = useControllable(props.columns, NO_COLUMNS)
  const [selectedId, setSelectedId] = useControllable(props.selectedTaskId, props.defaultSelectedTaskId ?? null)

  const options = useMemo(() => filterOptions(tasks), [tasks])
  const ids = useMemo(() => new Set(tasks.map((task) => task.id)), [tasks])
  const filtered = useMemo(() => filterTasks(tasks, filters), [tasks, filters])
  const stageIds = useMemo(() => stages?.map((stage) => stage.id), [stages])
  const someWithoutStage = useMemo(() => tasks.some((task) => !task.location), [tasks])
  const noStage = Boolean(stages) && (props.stageFilterNone ?? someWithoutStage)
  const stageCounts = useMemo(() => {
    if (!stages) return undefined
    const counts = countByStage(filterTasks(tasks, { ...filters, stage: undefined }))
    return Object.fromEntries([...stages.map((stage) => stage.id), NO_STAGE].map((id) => [id, counts[id] ?? 0]))
  }, [stages, tasks, filters])
  const grouped = useMemo(() => groupByStatus(filtered, columns), [filtered, columns])
  const summary = useMemo(() => summarize(filtered), [filtered])
  const selected = selectedId === null ? undefined : tasks.find((task) => task.id === selectedId)
  const live = mode === "live"

  const { bodyRef, focusPanelNext, focusCardNext, cardOfLastTask } = useBoardFocus(selectedId, {
    modal: detailPresentation !== "side",
  })
  const selectTask = useCallback(
    (id: string) => {
      focusPanelNext()
      controller.selectTask(id, { reason: "item-press" })
    },
    [controller, focusPanelNext],
  )
  const closePanel = useCallback(
    (reason: "close-press" | "escape-key" | "outside-press" | "imperative") => {
      focusCardNext()
      controller.selectTask(null, { reason })
    },
    [controller, focusCardNext],
  )

  const display = useMemo<TaskDisplayOptions & { labels: typeof labels }>(
    () => ({
      mode,
      now,
      locale,
      timeZone,
      formatCurrency,
      labels,
      agentApproval,
      onApproveProposal: live ? onApproveProposal : undefined,
      onRejectProposal: live ? onRejectProposal : undefined,
      onSelectTask: selectTask,
      canSelect: (id: string) => ids.has(id),
      agentAvatars,
      statusTones: tones,
      onOpenLink,
      stages,
    }),
    [
      mode,
      now,
      locale,
      timeZone,
      formatCurrency,
      labels,
      agentApproval,
      live,
      onApproveProposal,
      onRejectProposal,
      selectTask,
      ids,
      agentAvatars,
      tones,
      onOpenLink,
      stages,
    ],
  )

  const clearFilters = () => controller.filter(clearedFilters(filterControls), { reason: "clear-press" })

  let content: ReactNode
  if (filtered.length === 0) {
    content = (
      <AgentTaskBoardEmpty
        labels={labels}
        filtered={tasks.length > 0}
        canClear={activeFilters(filters, filterControls).length > 0}
        onClear={clearFilters}
      />
    )
  } else if (view === "table") {
    content = <AgentTaskBoardTable tasks={filtered} selectedTaskId={selectedId} display={display} />
  } else if (view === "backlog") {
    content = (
      <AgentTaskBoardBacklog
        tasks={filtered}
        selectedTaskId={selectedId}
        display={display}
        renderActions={renderBacklogActions}
      />
    )
  } else {
    content = (
      <AgentTaskBoardColumns
        columns={grouped}
        selectedTaskId={selectedId}
        display={display}
        tones={columnAccent === "tint" ? tones : undefined}
        renderCardActions={renderCardActions}
        onCollapsedChange={(status, collapsed) => {
          const next = withColumn(columns, status, { collapsed })
          setColumns(next)
          props.onColumnsChange?.(next)
        }}
      />
    )
  }

  return (
    <AgentTaskBoardRoot
      aria-label={labels.board}
      data-slot="agent-task-board"
      data-mode={mode}
      controller={controller}
      tasks={tasks}
      stageIds={stageIds}
      noStageLabel={labels.filters.noStage}
      view={view}
      onViewChange={(next) => {
        setView(next)
        props.onViewChange?.(next)
      }}
      filters={filters}
      onFiltersChange={(next) => {
        setFilters(next)
        props.onFiltersChange?.(next)
      }}
      selectedTaskId={selectedId}
      onSelectTask={(id) => {
        setSelectedId(id)
        props.onSelectTask?.(id)
      }}
      onOpenThread={onOpenThread && ((thread) => onOpenThread(thread))}
      onOpenLink={
        onOpenLink &&
        ((link, details) => {
          const task = tasks.find((candidate) => candidate.id === details.taskId)
          if (task) onOpenLink(link, task)
        })
      }
      className={cn("@container/agent-task-board min-w-0", props.className)}
    >
      <div data-slot="agent-task-board-density" data-density={density} className="flex flex-col gap-section">
        <AgentTaskBoardDetail
          header={
            <>
              <AgentTaskBoardToolbar
                options={options}
                filters={filters}
                view={view}
                labels={labels}
                controller={controller}
                generatedAt={mode === "snapshot" ? generatedAt : undefined}
                locale={locale}
                timeZone={timeZone}
                stages={stages}
                stageCounts={stageCounts}
                noStage={noStage}
                controls={filterControls}
              />
              <AgentTaskBoardSummary
                summary={summary}
                labels={labels}
                locale={locale}
                formatCurrency={formatCurrency}
              />
            </>
          }
          presentation={detailPresentation}
          bodyRef={bodyRef}
          selected={selected}
          display={display}
          onClose={closePanel}
          returnFocus={cardOfLastTask}
          renderThreadLink={renderThreadLink}
          onOpenThread={onOpenThread}
          renderLink={renderLink}
          renderAttachments={renderAttachments}
          renderLocation={renderLocation}
        >
          {content}
        </AgentTaskBoardDetail>
        <AgentTaskProposalsRoot
          aria-label={labels.proposals.group}
          className="sr-only"
          tasks={tasks}
          mode={mode}
          agentApproval={agentApproval}
          agentConfirm={labels.proposals.agentConfirm}
          onApproveProposal={live && onApproveProposal ? (id) => onApproveProposal(id) : undefined}
          onRejectProposal={live && onRejectProposal ? (id) => onRejectProposal(id) : undefined}
        />
      </div>
    </AgentTaskBoardRoot>
  )
}

export { AgentTaskBoard, NO_STAGE, agentTaskBoardLabels, agentTaskBoardLabelsEs, taskStatusAccentTones }
export type { AgentTaskBoardProps, ColumnAccent }

"use client"

import type { ReactNode, Ref } from "react"

import type { TaskLink, TaskView, ThreadRef } from "@/lib/agent-task-types"
import type { DetailPresentation } from "@/components/ui/agent-task-board-props"
import type { TaskDisplayOptions } from "@/components/ui/task-card"
import { TaskDetailDialog } from "@/components/ui/task-detail-dialog"
import { TaskDetailPanel, type CloseReason } from "@/components/ui/task-detail-panel"

type AgentTaskBoardDetailProps = {
  presentation: DetailPresentation
  /** The toolbar and summary above the board. */
  header: ReactNode
  /** The board or table. */
  children: ReactNode
  bodyRef: Ref<HTMLDivElement>
  selected: TaskView | undefined
  display: TaskDisplayOptions
  onClose: (reason: CloseReason | "imperative") => void
  returnFocus: () => HTMLElement | null
  renderThreadLink?: (thread: ThreadRef) => ReactNode
  onOpenThread?: (thread: ThreadRef) => void
  renderLink?: (link: TaskLink) => ReactNode
  renderAttachments?: (task: TaskView) => ReactNode
  renderLocation?: (task: TaskView) => ReactNode
}

function AgentTaskBoardDetail({
  presentation,
  header,
  children,
  bodyRef,
  selected,
  display,
  onClose,
  returnFocus,
  renderThreadLink,
  onOpenThread,
  renderLink,
  renderAttachments,
  renderLocation,
}: AgentTaskBoardDetailProps) {
  const threads = { renderThreadLink, onOpenThread, renderLink, renderAttachments, renderLocation }
  if (presentation !== "side") {
    return (
      <>
        {/* People can't reach the board behind a modal, so agents don't see its controls either; the board's own actions still work. */}
        <div data-agent-hidden={selected ? "" : undefined} className="flex flex-col gap-section">
          {header}
          <div ref={bodyRef}>{children}</div>
        </div>
        <TaskDetailDialog
          task={selected}
          presentation={presentation}
          {...display}
          {...threads}
          onClose={onClose}
          finalFocus={returnFocus}
        />
      </>
    )
  }
  return (
    <>
      {header}
      <div
        ref={bodyRef}
        className="flex flex-col gap-section @4xl/agent-task-board:flex-row @4xl/agent-task-board:items-start"
      >
        <div className="min-w-0 flex-1">{children}</div>
        {selected && (
          <TaskDetailPanel
            key={selected.id}
            task={selected}
            {...display}
            {...threads}
            onClose={onClose}
            className="sticky bottom-0 max-h-(--task-panel-max-height) @4xl/agent-task-board:top-0 @4xl/agent-task-board:bottom-auto @4xl/agent-task-board:w-(--task-panel-width) @4xl/agent-task-board:shrink-0"
          />
        )}
      </div>
    </>
  )
}

export { AgentTaskBoardDetail }

"use client"

import { ClockIcon } from "lucide-react"

import {
  NO_STAGE,
  activeFilters,
  type FilterControl,
  type FilterOptions,
  type TaskFilters,
} from "@/lib/agent-task-board-model"
import { formatInstant } from "@/lib/time"
import type { AgentTaskBoardController, BoardView } from "@/components/ui/agent-task-board-primitive"
import type { AgentTaskBoardLabels } from "@/components/ui/agent-task-labels"
import { Button } from "@/components/ui/button"
import { Field, FieldLabel } from "@/components/ui/field"
import { SearchField } from "@/components/ui/search-field"
import { SegmentedControl, SegmentedControlIndicator, SegmentedControlItem } from "@/components/ui/segmented-control"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectItemIndicator,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { StageFilter, type Stage } from "@/components/ui/stage-track"

type ChoiceKey = "project" | "profile" | "model"

const choiceSources = { project: "projects", profile: "profiles", model: "models" } as const
const anyLabel = { project: "allProjects", profile: "anyProfile", model: "anyModel" } as const

type FilterSelectProps = {
  name: ChoiceKey
  options: FilterOptions
  filters: TaskFilters
  labels: AgentTaskBoardLabels
  controller: AgentTaskBoardController
}

// "" stands for "any": the primitive's filter treats an empty value as clearing that filter.
function FilterSelect({ name, options, filters, labels, controller }: FilterSelectProps) {
  const items = [
    { value: "", label: labels.filters[anyLabel[name]] },
    ...options[choiceSources[name]].map((value) => ({ value, label: value })),
  ]
  return (
    <Field className="min-w-40 flex-1">
      <FieldLabel>{labels.filters[name]}</FieldLabel>
      <Select
        items={items}
        value={filters[name] ?? ""}
        onValueChange={(value) => controller.filter({ [name]: value || null }, { reason: "item-press" })}
      >
        <SelectTrigger>
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          {items.map((item) => (
            <SelectItem key={item.value} value={item.value}>
              <span className="min-w-0 truncate">{item.label}</span>
              <SelectItemIndicator />
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </Field>
  )
}

type AgentTaskBoardToolbarProps = {
  options: FilterOptions
  filters: TaskFilters
  view: BoardView
  labels: AgentTaskBoardLabels
  controller: AgentTaskBoardController
  /** Shown as the snapshot banner. */
  generatedAt?: string
  locale?: string
  timeZone?: string
  /** Shows a row of stage toggles when set. */
  stages?: readonly Stage[]
  /** Tasks per stage id under the other filters. */
  stageCounts?: Readonly<Record<string, number>>
  /** Adds the "No stage" toggle. */
  noStage?: boolean
  /** The filter controls that show; "Clear filters" clears only these. */
  controls: readonly FilterControl[]
}

const clearedFilters = (controls: readonly FilterControl[]) =>
  Object.fromEntries(controls.map((key) => [key, null])) as Record<FilterControl, null>

function AgentTaskBoardToolbar({
  options,
  filters,
  view,
  labels,
  controller,
  generatedAt,
  locale,
  timeZone,
  stages,
  stageCounts,
  noStage,
  controls,
}: AgentTaskBoardToolbarProps) {
  const filtered = activeFilters(filters, controls).length > 0
  const choices = (["project", "profile", "model"] as const).filter(
    (name) => controls.includes(name) && options[choiceSources[name]].length > 0,
  )
  const search = controls.includes("query")
  return (
    <div data-slot="agent-task-board-toolbar" className="@container/agent-task-board-toolbar flex flex-col gap-items">
      <div className="flex flex-wrap items-center justify-between gap-items">
        {generatedAt && (
          <p
            data-slot="agent-task-board-snapshot"
            className="flex items-center gap-inline text-sm text-muted-foreground"
          >
            <ClockIcon className="size-4" />
            <time dateTime={generatedAt}>{labels.snapshot(formatInstant(generatedAt, { locale, timeZone }))}</time>
          </p>
        )}
        <SegmentedControl<BoardView>
          aria-label={labels.views.group}
          className="ml-auto"
          value={view}
          onValueChange={(next) => next && controller.setView(next, { reason: "item-press" })}
        >
          <SegmentedControlIndicator />
          <SegmentedControlItem value="board">{labels.views.board}</SegmentedControlItem>
          <SegmentedControlItem value="table">{labels.views.table}</SegmentedControlItem>
          <SegmentedControlItem value="backlog">{labels.views.backlog}</SegmentedControlItem>
        </SegmentedControl>
      </div>
      {(search || choices.length > 0) && (
        <div className="flex">
          <fieldset aria-label={labels.filters.group} className="flex min-w-0 flex-1 flex-wrap items-end gap-items">
            {search && (
              <SearchField
                label={labels.filters.search}
                clearLabel={labels.filters.clearSearch}
                placeholder={labels.filters.searchPlaceholder}
                value={filters.query ?? ""}
                onValueChange={(value) => controller.filter({ query: value || null }, { reason: "input-change" })}
                className="min-w-56 flex-2"
              />
            )}
            {choices.map((name) => (
              <FilterSelect
                key={name}
                name={name}
                options={options}
                filters={filters}
                labels={labels}
                controller={controller}
              />
            ))}
            {filtered && (
              <Button
                variant="ghost"
                onClick={() => controller.filter(clearedFilters(controls), { reason: "clear-press" })}
              >
                {labels.filters.clear}
              </Button>
            )}
          </fieldset>
        </div>
      )}
      {controls.includes("stage") && stages && stages.length > 0 && (
        <StageFilter
          aria-label={labels.filters.stage}
          stages={stages}
          counts={stageCounts}
          noStage={noStage ? { value: NO_STAGE, label: labels.filters.noStage } : undefined}
          size="sm"
          locale={locale}
          value={filters.stage ?? []}
          onValueChange={(value) =>
            controller.filter({ stage: value.length > 0 ? value : null }, { reason: "item-press" })
          }
        />
      )}
    </div>
  )
}

export { AgentTaskBoardToolbar, clearedFilters }
export type { AgentTaskBoardToolbarProps }

"use client"

import { columnOrder, type ColumnConfig, type StatusColumn } from "@/lib/agent-task-board-model"
import type { ReactNode } from "react"

import type { TaskStatus, TaskView } from "@/lib/agent-task-types"
import type { Tone } from "@/lib/tone"
import type { AgentTaskBoardLabels } from "@/components/ui/agent-task-labels"
import { Board, BoardColumn, BoardColumnGroup } from "@/components/ui/board"
import { TaskCard, type TaskDisplayOptions } from "@/components/ui/task-card"

type AgentTaskBoardColumnsProps = {
  columns: StatusColumn[]
  selectedTaskId: string | null
  display: TaskDisplayOptions & { labels: AgentTaskBoardLabels }
  onCollapsedChange: (status: TaskStatus, collapsed: boolean) => void
  /** Each column's accent tone; none leaves the columns plain. */
  tones?: Record<TaskStatus, Tone>
  renderCardActions?: (task: TaskView) => ReactNode
}

// Writes the full order, so changing one column never moves it ahead of the columns that had no config yet.
function withColumn(columns: readonly ColumnConfig[], status: TaskStatus, change: Partial<ColumnConfig>) {
  const config = new Map(columns.map((column) => [column.status, column]))
  return columnOrder(columns).map((each) => {
    const column = config.get(each) ?? { status: each }
    return each === status ? { ...column, ...change } : column
  })
}

function AgentTaskBoardColumns({
  columns,
  selectedTaskId,
  display,
  onCollapsedChange,
  tones,
  renderCardActions,
}: AgentTaskBoardColumnsProps) {
  const { labels } = display
  const card = (task: TaskView) => (
    <TaskCard
      key={task.id}
      task={task}
      selected={task.id === selectedTaskId}
      renderActions={renderCardActions}
      {...display}
    />
  )

  return (
    <Board aria-label={labels.views.board}>
      {columns.map((column) => {
        const { ready = [], waiting = [] } = column.groups ?? {}
        const content = column.groups
          ? [
              ready.length > 0 && (
                <BoardColumnGroup key="ready" title={labels.ready} count={ready.length}>
                  {ready.map(card)}
                </BoardColumnGroup>
              ),
              waiting.length > 0 && (
                <BoardColumnGroup key="waiting" title={labels.waiting} count={waiting.length}>
                  {waiting.map(card)}
                </BoardColumnGroup>
              ),
            ].filter(Boolean)
          : column.tasks.map(card)
        return (
          <BoardColumn
            key={column.status}
            data-status={column.status}
            title={labels.columns[column.status]}
            tone={tones?.[column.status]}
            count={column.tasks.length}
            collapsed={column.collapsed}
            onCollapsedChange={(collapsed) => onCollapsedChange(column.status, collapsed)}
            empty={<p className="text-sm text-muted-foreground">{labels.empty.column}</p>}
            labels={labels.components.boardColumn}
          >
            {content}
          </BoardColumn>
        )
      })}
    </Board>
  )
}

export { AgentTaskBoardColumns, withColumn }
export type { AgentTaskBoardColumnsProps }

"use client"

import { Button } from "@ui-sdk/react/button"
import { useMemo, useState } from "react"
import { ChevronDownIcon, ChevronUpIcon, ChevronsUpDownIcon } from "lucide-react"

import {
  activeAttempt,
  attemptCount,
  sortTasks,
  taskCost,
  type SortDirection,
  type SortKey,
} from "@/lib/agent-task-board-model"
import type { TableColumn } from "@/lib/agent-task-board-labels"
import { effectiveAgent, type TaskView } from "@/lib/agent-task-types"
import { AgentBadge } from "@/components/ui/agent-badge"
import type { AgentTaskBoardLabels } from "@/components/ui/agent-task-labels"
import { QuantityValue } from "@/components/ui/quantity-value"
import { RelativeTime } from "@/components/ui/relative-time"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { TaskStatusIcon, TaskStatusPill } from "@/components/ui/task-status"
import type { TaskDisplayOptions } from "@/components/ui/task-card"
import { usageFormatter } from "@/components/ui/usage"

type AgentTaskBoardTableProps = {
  tasks: TaskView[]
  selectedTaskId: string | null
  display: TaskDisplayOptions & { labels: AgentTaskBoardLabels }
}

const columns: { key: TableColumn; sort?: SortKey; end?: boolean }[] = [
  { key: "id", sort: "id" },
  { key: "title", sort: "title" },
  { key: "status", sort: "status" },
  { key: "profile" },
  { key: "agent" },
  { key: "attempts", sort: "attempts", end: true },
  { key: "cost", sort: "cost", end: true },
  { key: "updatedAt", sort: "updatedAt" },
]

const headerButtonClassName =
  "-mx-(--chip-padding-x) inline-flex cursor-pointer items-center gap-inline rounded-control px-inset-chip py-inset-chip font-medium outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring [&_svg]:size-3.5"

function SortIcon({ direction }: { direction?: SortDirection }) {
  if (direction === "ascending") return <ChevronUpIcon />
  if (direction === "descending") return <ChevronDownIcon />
  return <ChevronsUpDownIcon />
}

function AgentTaskBoardTable({ tasks, selectedTaskId, display }: AgentTaskBoardTableProps) {
  const { labels, onSelectTask, now, locale, timeZone, formatCurrency, agentAvatars } = display
  const [sort, setSort] = useState<{ key: SortKey; direction: SortDirection }>({
    key: "status",
    direction: "ascending",
  })
  const rows = useMemo(() => sortTasks(tasks, sort.key, sort.direction), [tasks, sort])
  const formatCost = usageFormatter("cost", { locale, formatCurrency })
  const text = labels.table

  function toggle(key: SortKey) {
    setSort((current) => ({
      key,
      direction: current.key === key && current.direction === "ascending" ? "descending" : "ascending",
    }))
  }

  return (
    <Table aria-label={text.name} data-slot="agent-task-board-table">
      <TableHeader>
        <TableRow>
          {columns.map((column) => {
            const sorted = sort.key === column.sort ? sort.direction : undefined
            const label = text.columns[column.key]
            return (
              <TableHead
                key={column.key}
                scope="col"
                aria-sort={sorted}
                className={column.end ? "text-end" : undefined}
              >
                {column.sort ? (
                  <Button
                    aria-label={text.sortBy(label)}
                    className={headerButtonClassName}
                    onClick={() => column.sort && toggle(column.sort)}
                  >
                    {label}
                    <SortIcon direction={sorted} />
                  </Button>
                ) : (
                  label
                )}
              </TableHead>
            )
          })}
        </TableRow>
      </TableHeader>
      <TableBody>
        {rows.map((task) => {
          const attempt = activeAttempt(task)
          const selected = task.id === selectedTaskId
          return (
            <TableRow
              key={task.id}
              data-task-id={task.id}
              data-selected={selected ? "" : undefined}
              className="data-selected:bg-muted"
            >
              <TableCell className="font-mono text-xs text-muted-foreground">{task.id}</TableCell>
              <TableCell className="max-w-96">
                <Button
                  data-task-select=""
                  data-task-id={task.id}
                  aria-label={labels.card.open(task.id, task.title)}
                  aria-current={selected ? "true" : undefined}
                  title={task.title}
                  onClick={() => onSelectTask?.(task.id)}
                  className="max-w-full cursor-pointer truncate rounded-control text-start font-medium underline-offset-4 outline-none hover:underline focus-visible:ring-2 focus-visible:ring-ring"
                >
                  {task.title}
                </Button>
              </TableCell>
              <TableCell>
                <span className="inline-flex items-center gap-inline">
                  <TaskStatusIcon status={task.status} tone={display.statusTones?.[task.status]} />
                  <TaskStatusPill status={task.status} labels={labels.components.taskStatus} />
                </span>
              </TableCell>
              <TableCell className="text-muted-foreground">{task.profile ?? "—"}</TableCell>
              <TableCell className="max-w-56">
                {attempt ? (
                  <AgentBadge
                    agent={effectiveAgent(attempt)}
                    requested={attempt.configured}
                    labels={labels.components.agentBadge}
                    avatars={agentAvatars}
                  />
                ) : (
                  "—"
                )}
              </TableCell>
              <TableCell className="text-end tabular-nums">{attemptCount(task)}</TableCell>
              <TableCell className="text-end">
                <QuantityValue value={taskCost(task)} format={formatCost} labels={labels.components.usage?.quantity} />
              </TableCell>
              <TableCell className="text-muted-foreground">
                <RelativeTime value={task.updatedAt} now={now} locale={locale} timeZone={timeZone} />
              </TableCell>
            </TableRow>
          )
        })}
      </TableBody>
    </Table>
  )
}

